class Employee {
  name: string;
  sales?: number;
  calculateBonus() {
    if (this.sales && this.sales > 100000) return this.sales * 0.1;
    return 0;
  }
}
class SalesEmployee extends Employee { sales = 150000; }
class Engineer extends Employee { /* no sales */ }

class Invoice {
  id: string;
  printToPrinter() {
    console.log("Printing invoice", this.id);
  }
}
class PaperInvoice extends Invoice { paperFormat = "A4"; }
class EInvoice extends Invoice { emailAddress = "cust@example.com"; }

// Version A
class Invoice {
  id: string;
  type: "paper" | "electronic";
  print() {
    if (this.type === "paper") console.log("Printing on paper", this.id);
  }
}
class PaperInvoice extends Invoice { type = "paper"; }
class EInvoice extends Invoice { type = "electronic"; }

// Version B
abstract class BaseInvoice { id: string; abstract print(): void; }
class PaperInvoice2 extends BaseInvoice { print() { console.log("Printing on paper", this.id); } }
class EInvoice2 extends BaseInvoice { print() { /* no-op */ } }
